    assert.equal(s.input, "");
    assert.deepEqual(s.button, { disabled: false, text: "提交分派" });
    await assertUnchanged(h, ticket, "未分派", ticket.updatedAt, 0);

    // 空内容仍须先填写有效负责人，前端拦截且不发请求。
