var loaded = [];
// confirmed 记录列表已读取到的各工单最新内容（工单编号 -> 工单），
// 是“服务端当前工单”在本页面的最新快照：列表重新读取成功后逐张同步。
// 分派确认可能早于或晚于列表读取返回，合并双方时都不能让较旧的一方
// 撤回较新的一方（如等待期间另一页面又转交了工单）。
var confirmed = {};

// newerTicket 判断 a 是否不旧于 b：最近处理时间更晚，或时间相同但分派记录更全。
// 时间字符串是固定宽度格式，可直接按文字比较先后。
function newerTicket(a, b){
  var ta = a.updatedAt || "", tb = b.updatedAt || "";
  if (ta !== tb) return ta > tb;
  var la = Array.isArray(a.assignments) ? a.assignments.length : 0;
  var lb = Array.isArray(b.assignments) ? b.assignments.length : 0;
  return la >= lb;
}

// mergeAssignments 按发生顺序合并两次读取到的分派记录。同一时刻只会有
// 一次实际变化（服务端串行处理），同刻记录内容相同，按“新负责人”去重即可
// 保留双方记录；不同时刻的记录按时间（固定宽度字符串）升序排列。
function mergeAssignments(a, b){
  var byKey = {};
  var order = [];
  [a, b].forEach(function(recs){
    (Array.isArray(recs) ? recs : []).forEach(function(rec){
      var key = (rec.at || "") + "�" + (rec.to || "");
      if (!Object.prototype.hasOwnProperty.call(byKey, key)) {
        byKey[key] = rec;
        order.push(key);
      }
    });
  });
  return order.map(function(k){ return byKey[k]; }).sort(function(r1, r2){
    var a1 = r1.at || "", a2 = r2.at || "";
    if (a1 !== a2) return a1 < a2 ? -1 : 1;
    return 0;
  });
}

// mergeResultTicket 合并分派接口确认的结果与页面已知的最新工单内容。
// 分派请求在途期间工单可能已被另一页面转交：列表已显示转交后的内容时，
// 迟到的成功响应不能把负责人、最近处理时间与分派记录退回响应中的旧内容，
// 但本次操作确实成功，其分派记录仍应按发生顺序保留。返回合并后应展示的工单：
// 响应不旧于已知内容时采纳响应；否则保留当前负责人与后一次处理时间，
// 仅补齐本次操作对应的分派记录。
function mergeResultTicket(respTicket, known){
  if (!known || newerTicket(respTicket, known)) return respTicket;
  var mergedRecs = mergeAssignments(respTicket.assignments, known.assignments);
  var merged = Object.assign({}, known, {assignments: mergedRecs});
  return merged;
}

