// mergeResultTicket 合并分派接口确认的结果与页面已知的最新工单内容。
// 分派请求在途期间工单可能已被另一页面转交：列表已显示转交后的内容时，
// 迟到的成功响应不能把负责人、最近处理时间与分派记录退回响应中的旧内容，
// 但本次操作确实成功，其分派记录仍应按发生顺序保留。返回合并后应展示的工单：
// 响应不旧于已知内容时采纳响应；否则保留当前负责人与后一次处理时间，
// 仅补齐本次操作对应的分派记录。
function mergeResultTicket(respTicket, known){
  if (!known || newerTicket(respTicket, known)) return respTicket;
  var mergedRecs = mergeAssignments(respTicket.assignments, known.assignments);
  var merged = Object.assign({}, known, {assignments: mergedRecs});
  return merged;
}

